#!/usr/bin/env python3
"""
Bazaar Tracker MK XVIIIIII
pip install flask requests
python bazaar_mkv_boss.py
"""
import threading, json, time, webbrowser, requests, json, os, math
from flask import Flask, jsonify, Response, request

PORT      = 8742
API_URL   = "https://api.hypixel.net/v2/skyblock/bazaar"
TTL       = 55
_cache    = {"data": None, "ts": 0, "error": None}
_lock     = threading.Lock()
app       = Flask(__name__)

# ── BAZAAR API ────────────────────────────────────────────────────────────────
def fetch():
    try:
        r = requests.get(API_URL, timeout=10, headers={"User-Agent": "BazaarMKV/Boss"})
        r.raise_for_status()
        raw = r.json()
        if not raw.get("products"):
            raise ValueError("Invalid response")
        d = {}
        for pid, p in raw["products"].items():
            qs = p.get("quick_status", {})
            if not qs: continue
            d[pid] = {
                "s":  qs.get("sellPrice",     0),
                "b":  qs.get("buyPrice",      0),
                "sv": qs.get("sellMovingWeek",0),
                "bv": qs.get("buyMovingWeek", 0),
                "bo": qs.get("buyOrders",     0),
                "so": qs.get("sellOrders",    0),
            }
        with _lock:
            _cache["data"] = d; _cache["ts"] = time.time(); _cache["error"] = None
        print(f"[OK] {len(d)} produits {time.strftime('%H:%M:%S')}")
    except Exception as e:
        with _lock: _cache["error"] = str(e)
        print(f"[ERR] {e}")

def bg():
    while True:
        fetch(); time.sleep(TTL)

# ── PLAYER API (via Mojang) ───────────────────────────────────────────────────
def get_player(username):
    """Fetch player UUID via Mojang, then purse via Hypixel profiles API."""
    try:
        # Step 1: UUID from Mojang
        r = requests.get(
            f"https://api.mojang.com/users/profiles/minecraft/{username}",
            timeout=8, headers={"User-Agent": "BazaarMKV/Boss"}
        )
        if r.status_code != 200:
            return {"ok": False, "error": f"Joueur introuvable: {username}"}
        uuid = r.json()["id"]

        # Step 2: Skyblock profiles
        r2 = requests.get(
            f"https://api.hypixel.net/v2/skyblock/profiles?uuid={uuid}",
            timeout=10, headers={"User-Agent": "BazaarMKV/Boss"}
        )
        if r2.status_code != 200:
            return {"ok": False, "error": f"Profil Hypixel inaccessible (HTTP {r2.status_code})"}
        data = r2.json()
        if not data.get("profiles"):
            return {"ok": False, "error": "Aucun profil SkyBlock trouvé"}

        profiles = data["profiles"]
        active   = next((p for p in profiles if p.get("selected")), profiles[0])
        member   = active.get("members", {}).get(uuid, {})
        purse    = member.get("currencies", {}).get("coin_purse", 0)
        bank     = active.get("banking", {}).get("balance", 0)

        return {
            "ok": True, "username": username, "uuid": uuid,
            "profile": active.get("cute_name", "?"),
            "purse": purse, "bank": bank, "total": purse + bank,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}

# ── ROUTES ────────────────────────────────────────────────────────────────────
@app.route("/api/bazaar")
def api_bazaar():
    with _lock:
        age = time.time() - _cache["ts"] if _cache["ts"] else 999
        data = _cache["data"]; err = _cache["error"]
    if data is None:
        fetch()
        with _lock: data = _cache["data"]; err = _cache["error"]
        if data is None:
            return jsonify({"ok": False, "error": err or "Chargement"}), 503
    return jsonify({"ok": True, "ts": int(_cache["ts"]*1000),
                    "age": round(age,1), "next": max(0, round(TTL-age,0)), "data": data})

@app.route("/api/player")
def api_player():
    n = request.args.get("name", "").strip()
    if not n: return jsonify({"ok": False, "error": "?name= requis"}), 400
    return jsonify(get_player(n))

@app.route("/")
def index():
    return Response(build_html(), mimetype="text/html")

